def _b_sell_reason(self):
    if self.rsi_value is None:
        return False
    th = self.p["b_rsi_thresh"]
    if self.p["dof_rsi_exit"] == "cross":
        return self.rsi_prev is not None and self.rsi_prev <= th and self.rsi_value > th
    return self.rsi_value > th

